import sys

def find_divisible_number(n, arr):
    gcd = arr[0]
    for i in range(1, n):
        gcd = math.gcd(gcd, arr[i])

    if gcd == 1:
        return 1
    else:
        for num in arr:
            if num % gcd == 0:
                return num
        return -1

if __name__ == "__main__":
    import sys
    import math

    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    arr = list(map(int, data[1:]))

    result = find_divisible_number(n, arr)
    print(result)
